MESSAGES = {"telegram." + key: {"en": value[0], "uk": value[1]} for key, value in _PAIRS.items()}


def message(key: str, locale: str = "en", **values) -> str:
    return MESSAGES["telegram." + key]["uk" if locale == "uk" else "en"].format(**values)
